SELECT QNA_NO, QNA_USER_ID, CSR_NO, QNA_TITLE, QNA_CONTENTS, ANSWER_YN, REG_DATE, UPDT_DATE
FROM qna_info

	QNA_NO = #{keyword}
	QNA_TITLE LIKE CONCAT('%', #{keyword}, '%')
	AND REG_DATE >= #{registeredFrom}
	AND REG_DATE <= #{registeredTo}
	AND ANSWER_YN IN #{item}

ORDER BY REG_DATE DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(QNA_NO)
FROM qna_info

	QNA_NO = #{keyword}
	QNA_TITLE LIKE CONCAT('%', #{keyword}, '%')
	AND REG_DATE >= #{registeredFrom}
	AND REG_DATE <= #{registeredTo}
	AND ANSWER_YN IN #{item}

